/* parity.cpp -- the Rust engine against the C engine, cell by cell, in ONE binary.
 *
 * Both sort the same input in adjacent pairs, the order alternating from pair to pair (the discipline of bench_paired in
 * engines/c/bench_common.h: drift cancels inside a pair, the order bias across pairs); every output is verified once per cell
 * (ascending under <, and the input's bit patterns as a multiset). The first set of shapes is the scoreboard's seventeen
 * (engines/c/scoreboard.cpp), generated by the same code; the second (`extra`) is one the Rust engine was not tuned on.
 *
 *   columns: ns per element (the minimum over the pairs) for C and for Rust, then the MEDIAN of t(C) / t(Rust) over the pairs
 *   with its p10 and p90. Above 1: Rust is faster. PARITY = the median within 0.95-1.05.
 *
 * Build and run: bash parity/parity.sh [n] [pairs] [threads] [shape filter | extra | all]      (from engines/rust, in WSL) */
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdint>
#include <cmath>
#include <ctime>
#include <vector>
#include <string>
#include <algorithm>
extern "C" {
void logos_sort_f64(double *, size_t, int);
void logos_rs_sort_f64(double *, size_t, int);
}
static uint64_t RS = 7;
static uint64_t nr() { RS ^= RS << 13; RS ^= RS >> 7; RS ^= RS << 17; return RS; }
static double fr() { return (double)(nr() >> 11) / 9007199254740992.0; }
static double now_ms() { timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec * 1e3 + t.tv_nsec / 1e6; }

static void gen(const std::string &s, std::vector<double> &a) {
    size_t n = a.size(); RS = 7;
    if (s == "uniform") for (auto &v : a) v = fr() * 2e9 - 1e9;
    else if (s == "heavy_tail") for (auto &v : a) v = 1000.0 * std::pow(1.0 - fr() * 0.999999, -1.0 / 1.2);
    else if (s == "bimodal") for (auto &v : a) v = ((nr() & 1) ? 1e9 : -1e9) + fr() * 10.0;
    else if (s == "clustered") for (auto &v : a) v = (double)(nr() % 16) * 1e8 + fr() * 1e5;
    else if (s == "clustered_8") for (auto &v : a) v = (double)(nr() % 8) * 1e8 + fr() * 1e5;
    else if (s == "clustered_32") for (auto &v : a) v = (double)(nr() % 32) * 1e8 + fr() * 1e5;
    else if (s == "int_wide") for (auto &v : a) v = (double)(int32_t)nr();
    else if (s == "distinct_2") for (auto &v : a) v = (double)(nr() % 2) * 1e6 + 0.5;
    else if (s == "few_distinct") for (auto &v : a) v = (double)(nr() % 5) * 1e6;
    else if (s == "distinct_256") for (auto &v : a) v = (double)(nr() % 256) * 1000.0 + 0.5;
    else if (s == "distinct_65536") for (auto &v : a) v = (double)(nr() % 65536) * 1000.0 + 0.5;
    else if (s == "quantized") for (auto &v : a) v = (double)(nr() % 4096) / 64.0;
    else if (s == "near_sorted") { for (size_t i = 0; i < n; i++) a[i] = (double)i + 0.5; for (size_t k = 0; k < n / 100; k++) std::swap(a[nr() % n], a[nr() % n]); }
    else if (s == "sorted") for (size_t i = 0; i < n; i++) a[i] = (double)i * 1.5;
    else if (s == "reversed") for (size_t i = 0; i < n; i++) a[i] = (double)(n - i) * 1.5;
    else if (s == "block_perm" || s == "block_overlap") {
        size_t nb = 64, blk = (n + nb - 1) / nb; std::vector<size_t> perm(nb); for (size_t k = 0; k < nb; k++) perm[k] = k;
        for (size_t k = nb - 1; k > 0; k--) std::swap(perm[k], perm[nr() % (k + 1)]);
        for (size_t i = 0; i < n; i++) { size_t b = perm[i / blk]; double base = (double)b * (double)blk;
            if (s == "block_overlap" && (b & 7) == 1) base -= (double)blk * 0.1;
            a[i] = base + (double)(i % blk) + fr() * 0.5; }
    }
    /* ---- the second set: shapes the Rust engine was not tuned on ---- */
    else if (s == "normal") for (auto &v : a) { double u = fr(), w = fr(); v = std::sqrt(-2.0 * std::log(u + 1e-300)) * std::cos(6.283185307179586 * w); }
    else if (s == "lognormal") for (auto &v : a) { double u = fr(), w = fr(); v = std::exp(2.0 * std::sqrt(-2.0 * std::log(u + 1e-300)) * std::cos(6.283185307179586 * w)); }
    else if (s == "int_narrow") for (auto &v : a) v = (double)(nr() % 1000000);
    else if (s == "zipf") for (auto &v : a) v = std::floor(1.0 / (fr() + 1e-6));
    else if (s == "prices") for (auto &v : a) v = (double)(nr() % 200000) / 100.0;
    else if (s == "sawtooth") for (size_t i = 0; i < n; i++) a[i] = (double)(i % 4096) + fr() * 0.5;
    else if (s == "prefix_95") { size_t k = n - n / 20; for (size_t i = 0; i < k; i++) a[i] = (double)i + 0.5; for (size_t i = k; i < n; i++) a[i] = fr() * (double)n; }
    else if (s == "kinks") { for (size_t i = 0; i < n; i++) a[i] = (double)i + 0.5; for (size_t k = 0; k < n / 100; k++) { size_t i = nr() % (n - 1); std::swap(a[i], a[i + 1]); } }
    else if (s == "block_twist") {
        size_t nb = 64, blk = (n + nb - 1) / nb; std::vector<size_t> perm(nb); for (size_t k = 0; k < nb; k++) perm[k] = k;
        for (size_t k = nb - 1; k > 0; k--) std::swap(perm[k], perm[nr() % (k + 1)]);
        for (size_t i = 0; i < n; i++) { size_t b = perm[i / blk], o = i % blk; if (b & 1) o = blk - 1 - o; a[i] = (double)b * (double)blk + (double)o + 0.25; }
    }
    else if (s == "stairs") { size_t nb = 64, blk = (n + nb - 1) / nb; for (size_t i = 0; i < n; i++) a[i] = (double)(i / blk) * (double)blk * 0.8 + (double)(i % blk) + fr() * 0.5; }
    else if (s == "logs8") { size_t blk = (n + 7) / 8; for (size_t i = 0; i < n; i++) a[i] = (double)(i % blk) * 8.0 + (double)(i / blk) + fr() * 0.5; }
    else if (s == "latency") { for (size_t i = 0; i < n; i++) a[i] = (double)i + fr() * 200.0; }
    else if (s == "with_nan") { for (auto &v : a) v = fr(); a[n / 3] = NAN; }
    else if (s == "signed_zeros") for (auto &v : a) { uint64_t r = nr() % 4; v = r == 0 ? -0.0 : r == 1 ? 0.0 : fr() - 0.5; }
    else if (s == "infinities") for (auto &v : a) { uint64_t r = nr() % 64; v = r == 0 ? INFINITY : r == 1 ? -INFINITY : fr() * 1e300; }
    else if (s == "subnormals") for (auto &v : a) v = (double)(nr() % 1000003) * 4.9e-324;
    else { fprintf(stderr, "unknown shape %s\n", s.c_str()); exit(2); }
}
static const char *BOARD[] = { "uniform", "heavy_tail", "bimodal", "clustered", "clustered_8", "clustered_32", "int_wide", "distinct_2", "few_distinct", "distinct_256",
                               "distinct_65536", "quantized", "near_sorted", "sorted", "reversed", "block_perm", "block_overlap" };
static const char *EXTRA[] = { "normal", "lognormal", "int_narrow", "zipf", "prices", "sawtooth", "prefix_95", "kinks", "block_twist", "stairs", "logs8", "latency",
                               "signed_zeros", "infinities", "subnormals", "with_nan" };
static uint64_t bitsum(const double *a, size_t n) { uint64_t s = 0; for (size_t i = 0; i < n; i++) { uint64_t u; memcpy(&u, a + i, 8); s += u * 0x9E3779B97F4A7C15ULL + (u >> 29); } return s; }
static bool check(const double *w, size_t n, uint64_t want, bool ordered) {
    if (ordered) for (size_t i = 1; i < n; i++) if (w[i] < w[i - 1]) return false;
    return bitsum(w, n) == want;
}

int main(int argc, char **argv) {
    size_t n = argc > 1 ? strtoull(argv[1], 0, 10) : 8388608;
    int pairs = argc > 2 ? atoi(argv[2]) : 12; if (pairs < 2) pairs = 2;
    int Pmax = argc > 3 ? atoi(argv[3]) : 14;
    const char *filt = argc > 4 && argv[4][0] ? argv[4] : NULL;
    std::vector<const char *> shapes;
    bool extra = filt && !strcmp(filt, "extra"), all = filt && !strcmp(filt, "all");
    if (!extra) for (const char *s : BOARD) if (all || !filt || strstr(s, filt)) shapes.push_back(s);
    if (extra || all || (filt && shapes.empty())) for (const char *s : EXTRA) if (extra || all || strstr(s, filt)) shapes.push_back(s);
    std::vector<double> in(n), w(n);
    { std::vector<double> c(1 << 20); RS = 1; for (auto &x : c) x = fr(); double t = now_ms(); std::sort(c.begin(), c.end()); double ts = now_ms() - t;
      std::vector<char> m1(64 << 20, 1), m2(64 << 20, 2); t = now_ms(); memcpy(m2.data(), m1.data(), 64 << 20); double tm = now_ms() - t;
      printf("parity: n = %zu, %d adjacent pairs per cell, every output verified; calibration memcpy-64MB %.1f ms, std::sort-1M %.1f ms\n", n, pairs, tm, ts); }
    printf("ns per element (minimum); ratio = median of t(C) / t(Rust) over the pairs, above 1 = Rust faster\n");
    int nwrong = 0;
    std::vector<int> Ps; if (!getenv("PARITY_PAR_ONLY") && !(getenv("PARITY_ONCE") && Pmax > 1)) Ps.push_back(1); if (Pmax > 1) Ps.push_back(Pmax);
    for (int P : Ps) {
        int np = 0, nw = 0, nl = 0;
        printf("\n%d thread%s\n  %-15s %9s %9s   %7s %7s %7s\n", P, P > 1 ? "s" : "", "shape", "C", "Rust", "ratio", "p10", "p90");
        for (const char *s : shapes) {
            gen(s, in);
            uint64_t want = bitsum(in.data(), n);
            bool ordered = strcmp(s, "with_nan") != 0;
            memcpy(w.data(), in.data(), n * 8); logos_sort_f64(w.data(), n, P); bool okc = check(w.data(), n, want, ordered);
            if (getenv("PARITY_ONCE")) fprintf(stderr, "%s, %d thread%s\n", s, P, P > 1 ? "s" : "");
            memcpy(w.data(), in.data(), n * 8); logos_rs_sort_f64(w.data(), n, P); bool okr = check(w.data(), n, want, ordered);
            if (getenv("PARITY_ONCE")) { if (!okr) fprintf(stderr, "  WRONG OUTPUT\n"); continue; }
            double bc = 1e300, br = 1e300; std::vector<double> ratio;
            for (int r = 0; r < pairs; r++) {
                double tc = 0, tr = 0;
                for (int q = 0; q < 2; q++) {
                    memcpy(w.data(), in.data(), n * 8);
                    double t = now_ms();
                    if ((q ^ r) & 1) { logos_rs_sort_f64(w.data(), n, P); tr = now_ms() - t; } else { logos_sort_f64(w.data(), n, P); tc = now_ms() - t; }
                }
                bc = std::min(bc, tc); br = std::min(br, tr); ratio.push_back(tr > 0 ? tc / tr : 1.0);
            }
            std::sort(ratio.begin(), ratio.end());
            double med = pairs & 1 ? ratio[pairs / 2] : 0.5 * (ratio[pairs / 2 - 1] + ratio[pairs / 2]);
            const char *verdict = med > 1.05 ? "RUST" : med < 0.95 ? "behind" : "PARITY";
            if (med > 1.05) nw++; else if (med < 0.95) nl++; else np++;
            if (!okc || !okr) nwrong++;
            printf("  %-15s %8.2f%s %8.2f%s   %7.3f %7.3f %7.3f  %s\n", s, bc * 1e6 / (double)n, okc ? " " : "!", br * 1e6 / (double)n, okr ? " " : "!",
                   med, ratio[(int)(0.10 * pairs)], ratio[(int)(0.90 * pairs)], verdict);
            fflush(stdout);
        }
        printf("  -> %d thread%s: Rust faster on %d, parity on %d, behind on %d of %zu\n", P, P > 1 ? "s" : "", nw, np, nl, shapes.size());
    }
    printf("\n%s\n", nwrong ? "! = WRONG OUTPUT" : "every output correct");
    return nwrong ? 1 : 0;
}
